<?php
// Database credentials are generated by the installer and kept outside public source.
$config = __DIR__ . '/../secret/database.php';
if (!is_file($config)) {
    // Redirect only when this is a genuinely unconfigured installation
    // and the installer exists. An incomplete installation must not restart.
    $base = dirname(__DIR__);
    $installer = $base . '/install/index.php';
    $hasInstallState = is_file($base . '/secret/secret.php')
        || is_file($base . '/secret/installed.lock');
    if (!$hasInstallState && is_dir($base . '/install') && is_file($installer)) {
        // Relative to the application root, including subdirectory installs.
        $scriptDir = str_replace('\\', '/', dirname((string)($_SERVER['SCRIPT_NAME'] ?? '/')));
        // Scripts in admin/ or ajax/ must still target the application root.
        if (preg_match('~/(?:admin|ajax)$~', $scriptDir)) {
            $scriptDir = dirname($scriptDir);
        }
        $target = rtrim($scriptDir, '/') . '/install/';
        header('Location: ' . $target, true, 302);
        exit;
    }
    http_response_code(503);
    exit($hasInstallState
        ? 'MedChart configuration is incomplete. Please contact the administrator.'
        : 'MedChart is not installed and the installer folder is missing.');
}
$settings = require $config;
if (!is_array($settings)) { http_response_code(503); exit('Database configuration unavailable.'); }
try {
    $conn = new mysqli($settings['host'], $settings['username'], $settings['password'], $settings['database'], (int)$settings['port']);
    $conn->set_charset('utf8mb4');
} catch (Throwable $e) {
    error_log('MedChart database connection failed: ' . $e->getCode());
    http_response_code(503);
    exit('Service temporarily unavailable');
}
